<!doctype html><html><head><meta charset="utf-8"><title>Product Labels</title><style>body{font-family:Arial;margin:18px}.sheet{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.label{break-inside:avoid;text-align:center;border:1px dashed #999;padding:10px;min-height:145px}.name{font-weight:700}.code,.price{font-size:12px;margin-top:4px}.price{font-size:16px;font-weight:700}.qr{width:85px;height:85px;margin:7px auto}.barcode{max-width:100%;height:65px}@media print{button{display:none}.label{border-color:#ddd}}</style></head><body><button onclick="window.print()">Print Labels</button><div class="sheet">@foreach($products as $p)@for($i=0;$i<$copies;$i++)<div class="label"><div class="name">{{ $p->product_name }}</div><div class="code">{{ $p->product_code }}</div>@if($mode==='barcode')<svg class="barcode" data-value="{{ $p->barcode }}"></svg>@else<div class="qr" data-value="{{ route('products.show',$p) }}"></div>@endif<div class="price">&#8369;{{ number_format((float)$p->selling_price,2) }}</div></div>@endfor @endforeach</div><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>document.querySelectorAll('.barcode').forEach(x=>JsBarcode(x,x.dataset.value,{format:'CODE128',displayValue:true,height:45,margin:4,fontSize:11}));document.querySelectorAll('.qr').forEach(x=>new QRCode(x,{text:x.dataset.value,width:85,height:85}));</script></body></html>
